examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var small = ""
@State private var standard = ""
@State private var large = ""
@State private var invalid = "Invalid value"
@State private var disabled = ""
@State private var notes = ""

examples.code:
VStack {
    MonarchTextField("Name", text: $name, isRequired: true)
    MonarchTextField("Notes", text: $notes, axis: .vertical, lineLimit: 3...8)
    MonarchTextField("Account ID", text: .constant("acct_1042"), isReadOnly: true)
}

MonarchTextField("Amount", text: $amount, focus: $isFocused) {
    Text(verbatim: "$").accessibilityHidden(true)
} trailing: {
    MonarchButton("Clear amount", systemImage: "xmark.circle.fill", variant: .ghost, isIconOnly: true) {
        amount = ""
    }
}
